# Article prefixes of the two shipped domains: Cyrillic seed -> Latin. Only a prefix that still equals the old seed is
# changed; one the owner edited stays as it is.
PREFIXES = (("GENERAL_GOODS", "ТВ", "GD"), ("SERVICES", "УС", "SV"))


def latin_prefixes(apps, schema_editor):
    DomainType = apps.get_model("catalog", "DomainType")
    for code, old, new in PREFIXES:
        DomainType.objects.filter(code=code, sku_prefix=old).update(sku_prefix=new)


